func TestZZProbeStatusContract(t *testing.T) {
	// defaults
	rec := httptest.NewRecorder()
	w := &responseWriter{}
	w.reset(rec)
	if w.Status() != http.StatusOK {
		t.Errorf("default Status()=%d want 200", w.Status())
	}
	if w.Written() {
		t.Errorf("default Written()=true want false")
	}

	// WriteHeader(404) then Status
	w.WriteHeader(http.StatusNotFound)
	if w.Status() != http.StatusNotFound {
		t.Errorf("after WriteHeader(404) Status()=%d", w.Status())
	}
	if w.Written() {
		t.Errorf("after WriteHeader(404) Written()=true")
	}
	w.WriteHeaderNow()
	if rec.Code != http.StatusNotFound {
		t.Errorf("after WriteHeaderNow rec.Code=%d", rec.Code)
	}
	if w.Size() != 0 {
		t.Errorf("size=%d", w.Size())
	}

	// Write implies 200
	rec2 := httptest.NewRecorder()
	w2 := &responseWriter{}
	w2.reset(rec2)
	n, err := w2.Write([]byte("hello"))
	if n != 5 || err != nil {
		t.Errorf("write n=%d err=%v", n, err)
	}
	if w2.Status() != http.StatusOK || rec2.Code != http.StatusOK {
		t.Errorf("after Write Status()=%d rec.Code=%d", w2.Status(), rec2.Code)
	}
	if w2.Size() != 5 {
		t.Errorf("size=%d", w2.Size())
	}

	// WriteString implies 200
	rec3 := httptest.NewRecorder()
	w3 := &responseWriter{}
	w3.reset(rec3)
	if _, err := w3.WriteString("hi"); err != nil {
		t.Errorf("WriteString err=%v", err)
	}
	if w3.Status() != http.StatusOK || rec3.Code != http.StatusOK {
		t.Errorf("after WriteString Status()=%d rec.Code=%d", w3.Status(), rec3.Code)
	}

	// WriteHeader(0) / negative should be ignored
	rec4 := httptest.NewRecorder()
	w4 := &responseWriter{}
	w4.reset(rec4)
	w4.WriteHeader(0)
	if w4.Status() != http.StatusOK {
		t.Errorf("after WriteHeader(0) Status()=%d want 200", w4.Status())
	}
	w4.WriteHeader(-1)
	if w4.Status() != http.StatusOK {
		t.Errorf("after WriteHeader(-1) Status()=%d want 200", w4.Status())
	}

	// explicit code then Write
	rec5 := httptest.NewRecorder()
	w5 := &responseWriter{}
	w5.reset(rec5)
	w5.WriteHeader(http.StatusTeapot)
	w5.Write([]byte("x"))
	if rec5.Code != http.StatusTeapot {
		t.Errorf("after WriteHeader(418)+Write rec.Code=%d", rec5.Code)
	}
	if w5.Status() != http.StatusTeapot {
		t.Errorf("after WriteHeader(418)+Write Status()=%d", w5.Status())
	}

	// 1xx
	rec6 := httptest.NewRecorder()
	w6 := &responseWriter{}
	w6.reset(rec6)
	w6.WriteHeader(http.StatusEarlyHints)
	if w6.Status() != http.StatusEarlyHints {
		t.Errorf("after WriteHeader(103) Status()=%d", w6.Status())
	}
}

func TestZZProbeContextStatus(t *testing.T) {
	r := New()
	r.GET("/status", func(c *Context) {
		c.Status(http.StatusAccepted)
		if c.Writer.Status() != http.StatusAccepted {
			t.Errorf("in handler Status()=%d", c.Writer.Status())
		}
	})
	w := httptest.NewRecorder()
	req, _ := http.NewRequest(http.MethodGet, "/status", nil)
	r.ServeHTTP(w, req)
	if w.Code != http.StatusAccepted {
		t.Errorf("rec.Code=%d want 202", w.Code)
	}

	r2 := New()
