	r2.ServeHTTP(w2, req2)
	if w2.Code != http.StatusUnauthorized {
		t.Errorf("abort rec.Code=%d want 401", w2.Code)
	}

	r3 := New()
	w3 := httptest.NewRecorder()
	req3, _ := http.NewRequest(http.MethodGet, "/nope", nil)
	r3.ServeHTTP(w3, req3)
	if w3.Code != http.StatusNotFound {
		t.Errorf("404 rec.Code=%d", w3.Code)
	}

	// after written, WriteHeader should not change reported status
	rec := httptest.NewRecorder()
	wr := &responseWriter{}
	wr.reset(rec)
	wr.WriteHeader(http.StatusNotFound)
	wr.WriteHeaderNow()
	wr.WriteHeader(http.StatusInternalServerError)
	t.Logf("after-written WriteHeader(500): Status()=%d rec.Code=%d", wr.Status(), rec.Code)
}
